/**
 * `inactive` has never been enabled or its subscription has ended; `pending` awaits completion of its checkout and acceptance of its order; `active` accepts requests on the forwarding endpoints; `failed` means the enablement failed, as `failure_reason` states. An `inactive` or `failed` service can be enabled again.
 */
export type ServiceResourceStatus =
  (typeof ServiceResourceStatus)[keyof typeof ServiceResourceStatus];

export const ServiceResourceStatus = {
  inactive: "inactive",
  pending: "pending",
  active: "active",
  failed: "failed",
} as const;

/**
 * Why the enablement failed; null unless `status` is `failed`. `checkout_expired` means checkout was not completed before its Checkout Session expired; `order_declined` means Billing did not accept the order, for example because the billing account is suspended; `order_canceled` means the order was withdrawn; `order_expired` means it was not paid in time.
 * @nullable
 */
export type ServiceResourceFailureReason =
  | (typeof ServiceResourceFailureReason)[keyof typeof ServiceResourceFailureReason]
  | null;

export const ServiceResourceFailureReason = {
  checkout_expired: "checkout_expired",
  order_declined: "order_declined",
  order_canceled: "order_canceled",
  order_expired: "order_expired",
} as const;

/**
 * The model platform service of a project.
 */
export interface ServiceResource {
  /** `inactive` has never been enabled or its subscription has ended; `pending` awaits completion of its checkout and acceptance of its order; `active` accepts requests on the forwarding endpoints; `failed` means the enablement failed, as `failure_reason` states. An `inactive` or `failed` service can be enabled again. */
  status: ServiceResourceStatus;
  /**
   * Why the enablement failed; null unless `status` is `failed`. `checkout_expired` means checkout was not completed before its Checkout Session expired; `order_declined` means Billing did not accept the order, for example because the billing account is suspended; `order_canceled` means the order was withdrawn; `order_expired` means it was not paid in time.
   * @nullable
   */
  failure_reason: ServiceResourceFailureReason;
  /**
   * The Checkout Session of the latest enablement; null before any enablement.
   * @nullable
   */
  checkout_session_id: string | null;
  /**
   * The order that enabled the service, or that the latest enablement's checkout created; null before checkout completes.
   * @nullable
   */
  order_id: string | null;
  /**
   * The Billing plan the service is sold under; null where the service is not sold. Price enabling it with Billing's quote, giving this plan with the `recurring` price type, the `metered` usage type and a quantity of 1; token usage is priced per model, at the rates Billing holds for each model's `billing`.
   * @nullable
   */
  plan_id: string | null;
  /**
   * The Billing subscription that requests are billed under; null until an enablement's checkout completes.
   * @nullable
   */
  subscription_id: string | null;
  /**
   * When the service became active and billing began; null until then.
   * @nullable
   */
  activated_at: string | null;
  /**
   * When the subscription ended; null unless it has.
   * @nullable
   */
  ended_at: string | null;
}

/**
 * automatic completes checkout with the purchase: the best applicable account discount is applied, and the
 * order is created with its invoice issued and paid from eligible credit grants and available balance.
 * Insufficient funds fail the purchase with HTTP 422 BILLING_INSUFFICIENT_FUNDS; no Billing order, charge or
 * discount redemption is committed.
 * deferred creates an open Billing Checkout Session and charges nothing, even for a zero total. The customer
 * completes it through Billing, where a promotion code can be applied, and then pays the issued invoice; a
 * session not completed by its deadline expires.
 */
export type CheckoutMode = (typeof CheckoutMode)[keyof typeof CheckoutMode];

export const CheckoutMode = {
  automatic: "automatic",
  deferred: "deferred",
} as const;

/**
 * A decimal string, in the currency stated alongside it.
 *
 * **The currency is not part of this type.** It is carried by a `currency` field next to the
 * amount, or by the account the amount belongs to. Reading an amount without that field is
 * reading a number with no unit.
 *
 * It is a string rather than a JSON number because a JSON number is a float in most parsers,
 * and a float loses precision on the first arithmetic. Nothing on this platform puts an amount
 * through a float.
 */
export type Money = string;

/**
 * Shared checkout choices for a product purchase. The service may set them or forward its client's
 * choices unchanged; it does not need to read them, and Billing validates them. Omitting this object or
 * mode selects automatic checkout. Each purchase creates its own Checkout Session. Promotion codes are supplied
 * only to Billing. A service may retain a failed creation record when Billing refuses a purchase; no
 * infrastructure is created for that refusal.
 */
export interface CheckoutOptions {
  mode?: CheckoutMode;
  /**
   * Expected invoice total after discounts and tax, before applying credit grants or balance.
   * A different total fails with BILLING_AMOUNT_CHANGED without charging or reserving a discount.
   * Accepted only in automatic mode; with deferred it is refused with HTTP 400. For deferred
   * checkout, give the expected amount when completing it through Billing.
   */
  expected_amount?: Money & string;
  /**
   * Where the client goes after the customer finishes a deferred checkout. Any absolute URI with a
   * scheme, including mobile and desktop application schemes. Billing stores it without checking the
   * target; each client validates its own.
   * @maxLength 2048
   */
  return_url?: string;
}

export interface CreateServiceRequestBody {
  checkout?: CheckoutOptions;
}

/**
 * The service, `pending` until its order is accepted, and its Checkout Session.
 */
export interface CreateServiceResponseBody {
  service: ServiceResource;
  /** The Billing Checkout Session of this enablement. With deferred checkout, the customer completes it in Billing. */
  checkout_session_id: string;
  /**
   * The order created when checkout completes, at once for automatic checkout; null until then.
   * @nullable
   */
  order_id: string | null;
}

